mapper.select:
SELECT IFNULL(sum(device_num), 0) as deviceCountTotal, IFNULL(sum(dev_online_num), 0) as devCountOnline, IFNULL(sum(dev_offline_num), 0) as devCountOffline, IFNULL(sum(channel_num), 0) as channelCountTotal, IFNULL(sum(channel_online_num), 0) as channelCountOnline, IFNULL(sum(channel_offline_num), 0) as channelCountOffline FROM vm_statistics_devices dataTable where dataTable.tenant_id = #{param.tenantId} AND `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND `day` = DAY(NOW())
and dataTable.app_ver_code = #{param.appVerCode}
and dataTable.industry_code = #{param.industryCode}
${param.dataScope}

select distinct device_code, status from (SELECT d.device_code, d.device_status as status, t.tenant_id, vop.app_ver_code as app_ver_code, vop.industry_code as industry_code,t.accept_node as accept_node FROM vm_device_info_t d LEFT JOIN vm_order_devices t ON d.device_code = t.device_code and t.delete_flag = '0' LEFT JOIN vm_order_package vop on t.order_code = vop.order_code and t.delete_flag = '0' LEFT JOIN vm_order_customer voc on t.order_code = voc.order_code
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = d.device_code and vcdit.delete_flag = '0' and t.tenant_id = vcdit.tenant_id and vcdit.industry_code =t.industry_code AND vcdit.industry_code = vop.industry_code
WHERE d.delete_flag = '0' and voc.delete_flag = '0' and voc.ord_status in (0,1,2)
and d.category_code = #{categoryCode}
) dataTable where dataTable.tenant_id = #{tenantId} ${dataScope}

SELECT ch.channel_code, ch.channel_status as status FROM (select ord.device_code, ord.tenant_id, vop.app_ver_code as app_ver_code, vop.industry_code as industry_code,ord.accept_node as accept_node from vm_order_devices ord left join vm_order_package vop on vop.order_code = ord.order_code LEFT JOIN vm_order_customer voc on ord.order_code = voc.order_code where ord.delete_flag = '0' and vop.delete_flag = '0' and voc.delete_flag = '0' and voc.ord_status in (0,1,2) ) dataTable LEFT JOIN vm_channel_info_t ch ON dataTable.device_code = ch.device_code
join vm_checkpoint_device_info_t vcdit on vcdit.device_code = ch.device_code and vcdit.delete_flag = '0' and dataTable.tenant_id = vcdit.tenant_id and vcdit.industry_code =dataTable.industry_code
WHERE ch.delete_flag = '0' ${dataScope}
